import itertools

# We construct the ring R = M_2(F_2), the ring of 2x2 matrices over the finite field of 2 elements.
# This is a non-commutative ring.
# Elements are represented as tuples of 4 integers (mod 2): (a, b, c, d) for [[a, b], [c, d]]
elements = list(itertools.product([0, 1], repeat=4))

def add(x, y):
    return tuple((a + b) % 2 for a, b in zip(x, y))

def mul(x, y):
    return (
        (x[0]*y[0] + x[1]*y[2]) % 2,
        (x[0]*y[1] + x[1]*y[3]) % 2,
        (x[2]*y[0] + x[3]*y[2]) % 2,
        (x[2]*y[1] + x[3]*y[3]) % 2
    )

def is_zero(x):
    return all(a == 0 for a in x)

def is_identity(x):
    return x == (1, 0, 0, 1)

# Function to generate a two-sided ideal from a set of generators
def generate_ideal(generators):
    ideal = set(generators)
    ideal.add((0, 0, 0, 0))
    while True:
        new_elements = set(ideal)
        # Closure under addition
        for x in ideal:
            for y in ideal:
                new_elements.add(add(x, y))
        # Closure under left and right multiplication by any ring element
        for x in ideal:
            for r in elements:
                new_elements.add(mul(r, x))
                new_elements.add(mul(x, r))
        if len(new_elements) == len(ideal):
            break
        ideal = new_elements
    return frozenset(ideal)

# Find all two-sided ideals of R
ideals = set()
for x in elements:
    ideals.add(generate_ideal([x]))

# Define multiplication of two ideals A and B
def multiply_ideals(A, B):
    products = [mul(a, b) for a in A for b in B]
    return generate_ideal(products)

R_ideal = frozenset(elements)
prime_ideals = []

# An ideal P is prime if P != R and for any ideals A, B: AB \subseteq P implies A \subseteq P or B \subseteq P
for P in ideals:
    if P == R_ideal:
        continue
    is_prime = True
    for A in ideals:
        for B in ideals:
            AB = multiply_ideals(A, B)
            if AB.issubset(P):
                if not (A.issubset(P) or B.issubset(P)):
                    is_prime = False
                    break
        if not is_prime:
            break
    if is_prime:
        prime_ideals.append(P)

# REMAINING HYPOTHESIS: R has exactly one prime ideal
# M_2(F_2) is a simple ring, so its only two-sided ideals are {0} and R. 
# The zero ideal is its only prime ideal.
assert len(prime_ideals) == 1, f"Expected exactly 1 prime ideal, found {len(prime_ideals)}"

def is_unit(x):
    for y in elements:
        if is_identity(mul(x, y)) and is_identity(mul(y, x)):
            return True
    return False

def is_nilpotent(x):
    curr = x
    for _ in range(16):
        if is_zero(curr):
            return True
        curr = mul(curr, x)
    return False

# We need to find an element in R that is NEITHER a unit NOR a nilpotent element.
# Let x be the matrix [[1, 0], [0, 0]]
x = (1, 0, 0, 0)

unit_x = is_unit(x)
nilpotent_x = is_nilpotent(x)

# CONCLUSION MUST FAIL: "Every element of R is either a unit or a nilpotent element."
assert not (unit_x or nilpotent_x), "Conclusion holds (x is unit or nilpotent), but we need it to FAIL."

print("Counterexample found in M_2(F_2)!")
print(f"Matrix x = {x}")
print(f"Is unit? {unit_x}")
print(f"Is nilpotent? {nilpotent_x}")

# Counterexample to the conjecture: "In an integral domain, every prime element is irreducible"
# when the hypothesis "p is not a unit" is dropped.
# We use the integral domain Z (integers) and the element p = 1.

def is_unit(x):
    """Units in Z are 1 and -1."""
    return x in (1, -1)

def divides(a, b):
    """Returns True if a divides b."""
    if a == 0:
        return b == 0
    return b % a == 0

def is_prime_condition(p, elements):
    """
    Evaluates the prime divisibility condition: p | ab implies p | a or p | b.
    Since the non-unit hypothesis was dropped, this is the remaining property of being prime.
    """
    for a in elements:
        for b in elements:
            if divides(p, a * b):
                if not (divides(p, a) or divides(p, b)):
                    return False
    return True

def is_irreducible(p, elements):
    """
    An element is irreducible if it is a non-unit and cannot be factored into two non-units.
    """
    if is_unit(p):
        return False  # Irreducible elements must be non-units

    for a in elements:
        for b in elements:
            if a * b == p:
                if not (is_unit(a) or is_unit(b)):
                    return False
    return True

# [1] Let R be an integral domain. We use Z, represented by a finite subset for testing.
Z_elements = range(-100, 101)

# Counterexample: p = 1
p = 1

# [2] Let p be a non-zero element of R.
assert p != 0, "Hypothesis [2] failed: p must be non-zero"

# [3] p is a prime element of R (satisfies the prime divisibility condition).
assert is_prime_condition(p, Z_elements), "Hypothesis [3] failed: p must satisfy the prime condition"

# Conclusion: p is an irreducible element of R.
# This must FAIL because 1 is a unit, and irreducible elements are strictly non-units.
assert not is_irreducible(p, Z_elements), "Conclusion should fail: p is a unit, thus not irreducible"

print("Counterexample found!")
print(f"In the integral domain Z, p = {p} satisfies the prime divisibility condition.")
print(f"However, p = {p} is a unit, so it is NOT irreducible.")

