import itertools

# Counterexample: R = Z/4Z
R = [0, 1, 2, 3]

def add(a, b):
    return (a + b) % 4

def mul(a, b):
    return (a * b) % 4

# Check if R is an integral domain
is_domain = True
for x in R:
    if x != 0:
        for y in R:
            if y != 0 and mul(x, y) == 0:
                is_domain = False
                break

# A Principal Ideal Domain (PID) MUST be an integral domain.
# Since R has zero divisors (e.g., 2 * 2 = 0), it is not an integral domain, hence not a PID.
is_pid = False

# We define a function N: R \ {0} -> Z_{>0}
# N(1) = 1, N(2) = 2, N(3) = 1
N = {1: 1, 2: 2, 3: 1}

def divides(b, a):
    """Returns True if b divides a in R."""
    for c in R:
        if mul(b, c) == a:
            return True
    return False

# Verify that N is a Dedekind-Hasse norm on R
# A Dedekind-Hasse norm requires that for all a, b in R with b != 0:
# either b divides a, or there exists x in the ideal (a, b) with x != 0 and N(x) < N(b).
is_dh_norm = True
for a in R:
    for b in R:
        if b == 0:
            continue
        if divides(b, a):
            continue

        # Ideal generated by a and b: (a, b) = {s*a + t*b | s, t in R}
        ideal_ab = set()
        for s in R:
            for t in R:
                ideal_ab.add(add(mul(s, a), mul(t, b)))

        # Check if there is an element x in (a, b) with 0 < N(x) < N(b)
        found = False
        for x in ideal_ab:
            if x != 0 and N[x] < N[b]:
                found = True
                break

        if not found:
            is_dh_norm = False
            break

# Verify that our constructed norm is indeed a valid Dedekind-Hasse norm
assert is_dh_norm is True, "N must be a valid Dedekind-Hasse norm on R"

# The conclusion is: R is a PID iff R admits a Dedekind-Hasse norm.
conclusion_holds = (is_pid == is_dh_norm)

# Assert that the conclusion is FALSE (since is_pid is False, but is_dh_norm is True)
assert not conclusion_holds, "Conclusion should be false: R admits a D-H norm but is not a PID."

